detail.command:
mkdir -p /tmp/mrg
cp src/ui/index.ts /tmp/mrg/index.resolved.ts
git reset --hard 1b051708839c6a0b4094c1f74261e1937e59fc27
echo '=== source commit ==='
git log --oneline -1 0f78e5474ee45afe3fd7ea1bddea0ba88e3efde0
echo '=== merge by sha ==='
git merge --no-edit 0f78e5474ee45afe3fd7ea1bddea0ba88e3efde0 || echo '(conflict expected)'
cp /tmp/mrg/index.resolved.ts src/ui/index.ts
git checkout --theirs -- src/ui/ui.css
cat >> src/ui/ui.css <<'EOF'
.cpa-leaderboard {
  display: flex;
  justify-content: center;
}
.cpa-leaderboard .leaderboard {
  width: min(880px, 100%);
  max-height: none;
}
.cpa-note {
  margin: 0 0 18px;
  color: #91a7b9;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.04em;
}
EOF
echo '=== markers ==='
grep -rn '^<<<<<<< \|^>>>>>>> ' src/ || echo none
git add -A
echo '=== HEAD / MERGE_HEAD ==='
git rev-parse HEAD; git rev-parse MERGE_HEAD
echo '=== staged files ==='
git diff --cached --name-only | head -30
echo '=== line counts (ui + one course) ==='
wc -l src/ui/index.ts src/ui/ui.css src/courses/data/candy-factory.ts
echo '=== typecheck ==='
npm run typecheck 2>&1 | tail -20
echo '=== test ==='
npm test 2>&1 | grep -v 'getContext' | tail -12
echo '=== build ==='
npm run build 2>&1 | tail -6
